<?php
namespace Tests\Feature;
use App\Models\{User,Owner,Venue,Booking,BookingPayment,GatewayAccount,CheckoutAttempt};
use App\Services\VenueSettings;
use App\Services\Payments\{CheckoutWindow,PaymentService};
use Carbon\CarbonImmutable;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\Http;
use Illuminate\Support\Str;
use Tests\TestCase;
class CheckoutWindowTest extends TestCase {
 use RefreshDatabase;
 protected function setUp():void{parent::setUp();CarbonImmutable::setTestNow(CarbonImmutable::parse('2030-05-20T16:00:00Z'));}
 protected function tearDown():void{CarbonImmutable::setTestNow();parent::tearDown();}
 private function setupBooking(int $minutes=20,string $status='hold'):array{
  $u=User::factory()->create();$ou=User::factory()->create();$o=Owner::unguarded(fn()=>Owner::create(['user_id'=>$ou->id,'name'=>'Dueño','email'=>$ou->email,'password'=>'OwnerPassword12345','activated'=>true,'email_verified_at'=>now()]));
  $v=Venue::create(['owner_id'=>$ou->id,'owner_account_id'=>$o->id,'name'=>'Jardín','slug'=>'jardin-'.Str::lower(Str::random(6)),'published'=>true,'settings'=>array_replace(VenueSettings::defaults(),['capacity'=>100,'open_hour'=>0,'close_hour'=>47,'prep_minutes'=>0,'clean_minutes'=>0,'included_hours'=>8,'weekday_price'=>150000,'weekend_price'=>150000,'holiday_price'=>150000,'extra_hour_price'=>0,'deposit_value'=>30])]);
  $start=CarbonImmutable::now()->addMinutes($minutes);$b=Booking::create(['id'=>(string)Str::uuid(),'venue_id'=>$v->id,'user_id'=>$u->id,'event_date'=>$start->setTimezone('America/Mexico_City')->format('Y-m-d'),'starts_at'=>$start,'ends_at'=>$start->addHours(8),'blocked_from'=>$start,'blocked_until'=>$start->addHours(8),'guests'=>20,'total'=>150000,'deposit'=>45000,'quote'=>['timezone'=>'America/Mexico_City'],'status'=>$status,'expires_at'=>CarbonImmutable::now()->addMinutes(15)]);
  $g=GatewayAccount::create(['venue_id'=>$v->id,'provider'=>'paypal','enabled'=>true,'sandbox'=>true,'credentials'=>['client_id'=>'client','client_secret'=>'secret','merchant_id'=>'ABC23456789DE','webhook_id'=>'webhook']]);
  $this->actingAs($u);return [$u,$v,$b,$g];
 }
 private function paypalFake():void{Http::fake(['api-m.sandbox.paypal.com/v1/oauth2/token'=>Http::response(['access_token'=>'oauth']),'api-m.sandbox.paypal.com/v2/checkout/orders'=>Http::response(['id'=>'ORDER123','links'=>[['rel'=>'approve','href'=>'https://www.sandbox.paypal.com/checkoutnow?token=ORDER123']]])]);}
 private function start(Booking $b,string $provider='paypal',string $purpose='deposit'){return $this->postJson('/api/bookings/'.$b->id.'/checkout',['provider'=>$provider,'purpose'=>$purpose,'policy_accepted'=>true,'phone'=>'+523121234567']);}
 public function test_paypal_accepts_near_event_without_old_thirty_minute_buffer():void{[$u,$v,$b]=$this->setupBooking(20);$this->paypalFake();$a=$this->start($b)->assertOk()->json();$this->assertSame(CarbonImmutable::now()->addMinutes(15)->timestamp,CarbonImmutable::parse($a['expires_at'])->timestamp);$this->assertSame(0,$b->payments()->count());}
 public function test_online_hold_expiry_is_capped_at_event_start():void{[$u,$v,$b]=$this->setupBooking(7);$this->paypalFake();$a=$this->start($b)->assertOk()->json();$this->assertSame($b->starts_at->timestamp,CarbonImmutable::parse($a['expires_at'])->timestamp);$this->assertSame($b->starts_at->timestamp,$b->fresh()->expires_at->timestamp);}
 public function test_online_allows_exactly_five_minutes_and_rejects_less_without_http():void{[$u,$v,$b]=$this->setupBooking(5);$this->paypalFake();$this->start($b)->assertOk();[$u,$v,$b]=$this->setupBooking(4);Http::fake();$this->start($b)->assertUnprocessable()->assertSee('al menos 5 minutos');Http::assertNothingSent();$this->assertSame(0,$b->checkoutAttempts()->count());}
 public function test_expired_hold_and_past_event_do_not_create_payment_orders():void{[$u,$v,$b]=$this->setupBooking(-1);Http::fake();$this->start($b)->assertUnprocessable()->assertJsonPath('message',fn($m)=>str_contains($m,'ya comenzó'));[$u,$v,$b]=$this->setupBooking(120);$b->update(['expires_at'=>CarbonImmutable::now()->subMinute()]);$this->start($b)->assertUnprocessable()->assertJsonPath('message',fn($m)=>str_contains($m,'apartado venció'));Http::assertNothingSent();}
 public function test_options_identify_oxxo_restriction_before_submission_and_include_local_date():void{[$u,$v,$b]=$this->setupBooking(20);GatewayAccount::create(['venue_id'=>$v->id,'provider'=>'oxxo','enabled'=>true,'sandbox'=>true,'credentials'=>['private_key'=>'key','webhook_public_key'=>'rsa']]);$r=$this->getJson('/api/bookings/'.$b->id.'/payment-options')->assertOk()->assertJsonPath('booking.timezone','America/Mexico_City')->assertJsonPath('booking.venue_name','Jardín')->json();$providers=collect($r['providers'])->keyBy('provider');$this->assertTrue($providers['paypal']['available']);$this->assertFalse($providers['oxxo']['available']);$this->assertStringContainsString('35 minutos',$providers['oxxo']['unavailable_reason']);}
 public function test_oxxo_keeps_thirty_minute_buffer_and_does_not_confirm_on_reference():void{[$u,$v,$b]=$this->setupBooking(45);GatewayAccount::create(['venue_id'=>$v->id,'provider'=>'oxxo','enabled'=>true,'sandbox'=>true,'credentials'=>['private_key'=>'key','webhook_public_key'=>'rsa']]);Http::fake(['api.digitalfemsa.io/orders'=>Http::response(['id'=>'ord123','livemode'=>false,'charges'=>['data'=>[['payment_method'=>['reference'=>'1234567890']]]]])]);$a=$this->start($b,'oxxo')->assertOk()->assertJsonPath('checkout.reference','1234567890')->json();$this->assertSame($b->starts_at->subMinutes(30)->timestamp,CarbonImmutable::parse($a['expires_at'])->timestamp);$this->assertSame('hold',$b->fresh()->status);$this->assertSame(0,$b->payments()->count());}
 private function deposit(Booking $b):void{BookingPayment::create(['id'=>(string)Str::uuid(),'booking_id'=>$b->id,'recorded_by'=>$b->user_id,'amount'=>45000,'method'=>'cash','reference'=>'Anticipo','idempotency_key'=>(string)Str::uuid()]);}
 public function test_confirmed_balance_can_start_after_event_and_has_normal_online_window():void{[$u,$v,$b]=$this->setupBooking(-30,'confirmed');$this->deposit($b);$this->paypalFake();$a=$this->start($b,'paypal','balance')->assertOk()->assertJsonPath('amount',105000)->json();$this->assertSame(CarbonImmutable::now()->addMinutes(15)->timestamp,CarbonImmutable::parse($a['expires_at'])->timestamp);}
 public function test_confirmed_balance_is_captured_and_applied_after_start_without_false_review():void{[$u,$v,$b,$g]=$this->setupBooking(-30,'confirmed');$this->deposit($b);$a=CheckoutAttempt::create(['id'=>(string)Str::uuid(),'booking_id'=>$b->id,'gateway_account_id'=>$g->id,'provider'=>'paypal','amount'=>105000,'currency'=>'MXN','status'=>'pending','external_id'=>'ORDER123','expires_at'=>CarbonImmutable::now()->addMinutes(15)]);$unit=['custom_id'=>$a->id,'payee'=>['merchant_id'=>'ABC23456789DE'],'amount'=>['currency_code'=>'MXN','value'=>'1050.00']];$paidUnit=$unit;$paidUnit['payments']=['captures'=>[['id'=>'CAPTURE123','status'=>'COMPLETED','amount'=>['currency_code'=>'MXN','value'=>'1050.00']]]];Http::fake(['api-m.sandbox.paypal.com/v1/oauth2/token'=>Http::response(['access_token'=>'oauth']),'api-m.sandbox.paypal.com/v2/checkout/orders/ORDER123'=>Http::sequence()->push(['id'=>'ORDER123','status'=>'APPROVED','purchase_units'=>[$unit]])->push(['id'=>'ORDER123','status'=>'COMPLETED','purchase_units'=>[$paidUnit]]),'api-m.sandbox.paypal.com/v2/checkout/orders/ORDER123/capture'=>Http::response(['status'=>'COMPLETED'])]);$this->postJson('/api/checkout/'.$a->id.'/capture')->assertOk()->assertJsonPath('status','paid');$this->assertSame(150000,$b->fresh()->paid_total);$this->assertNull($b->fresh()->payment_attention);$this->assertSame('confirmed',$b->fresh()->status);}
 public function test_payment_for_past_unconfirmed_event_is_recorded_for_review_never_confirmed():void{[$u,$v,$b,$g]=$this->setupBooking(-30);$a=CheckoutAttempt::create(['id'=>(string)Str::uuid(),'booking_id'=>$b->id,'gateway_account_id'=>$g->id,'provider'=>'paypal','amount'=>45000,'currency'=>'MXN','status'=>'pending','external_id'=>'ORDER123','expires_at'=>CarbonImmutable::now()->subMinute()]);app(PaymentService::class)->settle($g,['reference'=>$a->id,'amount'=>45000,'currency'=>'MXN','merchant'=>'ABC23456789DE','paid'=>true,'transaction'=>'CAPTURE123','external_id'=>'ORDER123']);$this->assertSame('review',$a->fresh()->status);$this->assertSame('hold',$b->fresh()->status);$this->assertSame(45000,$b->fresh()->paid_total);}
 public function test_expired_attempt_does_not_issue_new_paypal_capture():void{[$u,$v,$b,$g]=$this->setupBooking(120);$a=CheckoutAttempt::create(['id'=>(string)Str::uuid(),'booking_id'=>$b->id,'gateway_account_id'=>$g->id,'provider'=>'paypal','amount'=>45000,'currency'=>'MXN','status'=>'pending','external_id'=>'ORDER123','expires_at'=>CarbonImmutable::now()->subSecond()]);Http::fake(['api-m.sandbox.paypal.com/v1/oauth2/token'=>Http::response(['access_token'=>'oauth']),'api-m.sandbox.paypal.com/v2/checkout/orders/ORDER123'=>Http::response(['id'=>'ORDER123','status'=>'APPROVED','purchase_units'=>[['custom_id'=>$a->id,'payee'=>['merchant_id'=>'ABC23456789DE'],'amount'=>['currency_code'=>'MXN','value'=>'450.00']]]])]);$this->postJson('/api/checkout/'.$a->id.'/capture')->assertUnprocessable()->assertJsonPath('message',fn($m)=>str_contains($m,'intento de pago venció'));Http::assertNotSent(fn($r)=>str_ends_with($r->url(),'/capture'));$this->assertSame(0,$b->payments()->count());}
 public function test_cancelled_reservation_and_zero_balance_stay_blocked():void{[$u,$v,$b]=$this->setupBooking(120,'cancelled');Http::fake();$this->start($b)->assertUnprocessable();$b->update(['status'=>'confirmed','total'=>0,'deposit'=>0]);$this->start($b,'paypal','balance')->assertUnprocessable();Http::assertNothingSent();}
}
